 23	function danglingRank(int $playerId): void
 24	{
 25	    Highscore::unguarded(fn () => Highscore::updateOrCreate(
 26	        ['player_id' => $playerId],
 27	        ['general' => 500, 'general_rank' => 2, 'economy' => 500, 'research' => 500],
 28	    ));
 29	}
