 31	function danglingProfile(int $playerId): void
 32	{
 33	    AiProfile::create([
 34	        'player_id' => $playerId,
 35	        'archetype' => AiArchetype::Miner,
 36	        'skill_band' => AiSkillBand::Standard,
 37	        'activity_band' => AiActivityBand::Regular,
 38	        'random_seed' => 42,
 39	        'enabled' => true,
 40	    ]);
