 44	{
 45	    $founder = User::factory()->create(['lang' => 'en']);
 46	    $club = Alliance::unguarded(fn (): Alliance => Alliance::create([
 47	        'alliance_tag' => $tag,
 48	        'alliance_name' => 'Alliance ' . $tag,
 49	        'founder_user_id' => $founder->id,
 50	        'is_open' => true,
